	public function publicationSummary(int $limit=50):array{$limit=max(1,min(100,$limit));$start=microtime(true);$queriesBefore=function_exists('get_num_queries')?(int)get_num_queries():null;$memoryBefore=memory_get_usage(true);$candidates=$this->candidates($limit);$included=0;$wouldIndex=0;$readyIfEnabled=0;$reasons=array();foreach($candidates as $candidate){if(!empty($candidate['would_index'])){$wouldIndex++;}if(!empty($candidate['publication_ready_if_global_on'])){$readyIfEnabled++;}if(!empty($candidate['sitemap_included'])){$included++;}foreach((array)($candidate['exclusion_reasons']??array()) as $reason){$reasons[$reason]=($reasons[$reason]??0)+1;}}ksort($reasons,SORT_STRING);$queriesAfter=function_exists('get_num_queries')?(int)get_num_queries():null;return array('contract'=>'etg.dfsb.publication-summary.v2','authorizing'=>false,'read_only'=>true,'global_enabled'=>$this->config->enabled(),'configuration_revision'=>$this->config->revision(),'candidate_count'=>count($candidates),'would_index_count'=>$wouldIndex,'publication_ready_if_global_on_count'=>$readyIfEnabled,'sitemap_included_count'=>$included,'exclusion_reasons'=>$reasons,'performance'=>array('elapsed_ms'=>(int)round((microtime(true)-$start)*1000),'query_count_delta'=>null!==$queriesBefore&&null!==$queriesAfter?max(0,$queriesAfter-$queriesBefore):null,'memory_delta_bytes'=>max(0,memory_get_usage(true)-$memoryBefore),'peak_memory_bytes'=>memory_get_peak_usage(true)),'cache'=>$this->cacheStats(),'limits'=>array('preview'=>$limit,'global_publication'=>$this->effectivePublicationLimit(self::MAX_PUBLICATION_URLS),'hard_publication'=>self::MAX_PUBLICATION_URLS,'candidate_evaluation_budget'=>max(1,min(self::MAX_PUBLICATION_URLS,(int)$this->config->get('publication_candidate_evaluation_budget',50)))),'candidates'=>$candidates);}
